// Independent revision-09 BCRH-PERSIST checker.
// This namespace consumes only the raw public ABI record and constants.  It
// deliberately does not call the production scorer's state, legality, route,
// transition, schedule, weight, floor, score, digest, or tie helpers.
namespace independent_checker {
constexpr int NUL=255;
struct A{int rank,opaque,fast,radio,node,from,to,remaining,dest,token,state,elapsed,energy;};
struct S{std::vector<A>a;std::array<int,4>clear{};int failed=0,time=0;};
struct C{std::array<int,4>o{};};
struct Big{std::array<std::uint64_t,4>x{};static Big make(std::uint64_t v){Big b;b.x[0]=v;return b;}void plus(const Big&b){unsigned char c=0;for(int i=0;i<4;++i)c=_addcarry_u64(c,x[i],b.x[i],&x[i]);if(c)throw std::overflow_error("checker add");}Big times(std::uint64_t v)const{Big z;std::uint64_t carry=0;for(int i=0;i<4;++i){std::uint64_t hi=0,lo=_umul128(x[i],v,&hi),sum=0;unsigned char c=_addcarry_u64(0,lo,carry,&sum);z.x[i]=sum;if(i==3&&(hi||c))throw std::overflow_error("checker mul");carry=hi+c;}return z;}friend bool operator==(const Big&a,const Big&b){return a.x==b.x;}friend bool operator!=(const Big&a,const Big&b){return!(a==b);}friend bool operator>(const Big&a,const Big&b){for(int i=3;i>=0;--i)if(a.x[i]!=b.x[i])return a.x[i]>b.x[i];return false;}};
struct Schedule{std::array<std::array<std::array<int,16>,6>,2>d{};};
struct Weight{std::array<std::array<Big,16>,6>total{},fail{};Big accrued_total,accrued_fail;std::uint64_t scale=0;};
struct Score{int fn=0,fd=1;Big objective;int releases=0;std::array<int,4>serial{};};
struct Record{C command;Score score;};
struct Evaluation{std::vector<Record>records;std::size_t selected=0;std::uint64_t digest=0;};

int edge_seconds(bool fast,int a,int b){int t=0;if((a==0&&b==1)||(a==1&&b==0)||(a==1&&b==2)||(a==2&&b==1)||(a==3&&b==4)||(a==4&&b==3))t=20;else if((a==0&&b==3)||(a==3&&b==0))t=30;else if((a==1&&b==3)||(a==3&&b==1))t=40;else throw std::logic_error("checker nonedge");return fast?std::max(5,5*((3*t+19)/20)):t;}
int next_node(int a,int b){if(a==b)return b;static const int next[5][5]={{0,1,1,3,3},{0,1,2,3,3},{1,1,2,1,1},{0,1,1,3,4},{3,3,3,3,4}};return next[a][b];}
int token_node(int t){return t<2?(t?1:2):(t==2?4:3);}int acquire_seconds(int t){return(t==0||t==2)?6:4;}
bool moving(const A&a){return a.remaining>0||a.node!=a.dest;}
int find(const S&s,int rank){for(std::size_t i=0;i<s.a.size();++i)if(s.a[i].rank==rank)return(int)i;return-1;}
void route(A&a,int dest){a.dest=dest;if(a.node==dest){a.from=a.to=-1;a.remaining=0;return;}int n=next_node(a.node,dest);a.from=a.node;a.to=n;a.remaining=edge_seconds(a.fast,a.node,n);}
void continue_route(A&a){if(a.node==a.dest){a.from=a.to=-1;a.remaining=0;}else{int n=next_node(a.node,a.dest);a.from=a.node;a.to=n;a.remaining=edge_seconds(a.fast,a.node,n);}}
int travel(A a,int dest){int seconds=a.remaining;if(a.remaining)a.node=a.to;while(a.node!=dest){int n=next_node(a.node,dest);seconds+=edge_seconds(a.fast,a.node,n);a.node=n;}return seconds;}
std::pair<int,int> contingency(const S&s,const A&source,int token){if(moving(source))return{0,0};A a=source;int target=token_node(token);bool retain=a.token==token&&a.node==target;int low=a.energy;if(!retain){route(a,target);a.token=token;a.state=1;a.elapsed=0;}int clearance=retain?0:s.clear[token];if(!retain)for(const auto&other:s.a)if(other.rank!=a.rank&&other.token==token&&other.state>0)clearance=std::max(clearance,1);int eta=retain?(a.state==2?0:acquire_seconds(token)-a.elapsed):std::max({travel(source,target),clearance,(token==(s.failed==1?0:2)&&s.time>=0)?std::max(0,20-s.time):0})+acquire_seconds(token);for(int second=0;second<400;++second){if(second>0&&second%20==0&&!moving(a)&&a.node!=0){a.token=-1;a.state=0;a.elapsed=0;route(a,0);}if(second>=20&&a.node==0&&!moving(a))break;if(a.remaining){a.energy-=a.fast?6:5;if(--a.remaining==0){a.node=a.to;continue_route(a);}}else if(a.node==target&&clearance==0&&!(token==(s.failed==1?0:2)&&s.time+second>=0&&s.time+second<20)){if(a.state==2)a.energy-=(token==0||token==2)?2:1;else if(++a.elapsed==acquire_seconds(token))a.state=2;}low=std::min(low,a.energy);if(clearance)--clearance;}return{eta,low-100};}
bool fixed(const S&s,int token,int&rank){for(const auto&a:s.a)if(a.token==token&&moving(a)){rank=a.rank;return true;}rank=NUL;return false;}
int command_error(const S&s,const C&c){std::array<bool,9>used{};for(int t=0;t<4;++t){int occupant;if(fixed(s,t,occupant)&&c.o[t]!=occupant)return 10+t;int r=c.o[t];if(r==NUL)continue;if(r<1||r>8||used[r])return 20+t;used[r]=true;int i=find(s,r);if(i<0)return 30+t;if(moving(s.a[i])&&s.a[i].token!=t)return 35+t;if(!moving(s.a[i])&&contingency(s,s.a[i],t).second<0)return 40+t;}return 0;}
std::vector<C> enumerate(const S&s){std::vector<C>out;int radix=(int)s.a.size()+1;std::uint64_t end=1;for(int i=0;i<4;++i)end*=radix;for(std::uint64_t code=0;code<end;++code){std::uint64_t x=code;C c;for(int t=0;t<4;++t){int digit=(int)(x%radix);x/=radix;c.o[t]=digit?s.a[digit-1].rank:NUL;}if(!command_error(s,c))out.push_back(c);}std::sort(out.begin(),out.end(),[](const C&a,const C&b){return a.o<b.o;});return out;}
int apply(S&s,const C&c){int error=command_error(s,c);if(error)return error;for(auto&a:s.a){if(moving(a))continue;int assigned=-1;for(int t=0;t<4;++t)if(c.o[t]==a.rank)assigned=t;if(a.state>0&&a.token>=0&&assigned!=a.token)s.clear[a.token]=std::max(s.clear[a.token],1);if(assigned!=a.token){a.state=assigned<0?0:1;a.elapsed=0;}a.token=assigned;if(assigned<0)route(a,0);else route(a,token_node(assigned));}return 0;}
std::array<int,2> delivery(const S&s,int q1,int q2,int h1,int h2){std::array<int,2>d{};for(int z=0;z<2;++z){int er=0,rr=0;for(const auto&a:s.a){if(a.state==2&&a.token==(z?2:0))er=a.radio;if(a.state==2&&a.token==(z?3:1))rr=a.radio;}int q=z?q2:q1,h=z?h2:h1;d[z]=er?(!h?std::min(q,er):(rr?std::min({q,er,rr}):0)):0;}return d;}
void tick(S&s,int q1,int q2,int h1,int h2){for(auto&a:s.a){if(a.remaining){a.energy-=a.fast?6:5;if(--a.remaining==0){a.node=a.to;continue_route(a);}}else if(a.token<0&&a.node==0)a.energy=std::min(800,a.energy+10);else if(a.state==2)a.energy-=(a.token==0||a.token==2)?2:1;else if(a.token>=0&&a.node==token_node(a.token)&&s.clear[a.token]==0&&!(a.token==(s.failed==1?0:2)&&s.time>=0&&s.time<20)){if(++a.elapsed==acquire_seconds(a.token))a.state=2;}}for(int&c:s.clear)if(c)--c;s.time++;}
void decode(int e,int&q1,int&q2,int&h1,int&h2){q1=1+(e&1);q2=1+((e>>1)&1);h1=(e>>2)&1;h2=(e>>3)&1;}
int state_index_local(int q1,int q2,int h1,int h2){return(q1-1)|((q2-1)<<1)|(h1<<2)|(h2<<3);}
int one_transition(int from,int to,bool obstruction){if(!obstruction){static const int n[2][2]={{8,2},{3,7}};return n[from][to];}static const int n[2][2]={{4,1},{2,3}};return n[from][to];}
std::uint64_t transition(int from,int to){int a,b,c,d,w,x,y,z;decode(from,a,b,c,d);decode(to,w,x,y,z);return(std::uint64_t)one_transition(a-1,w-1,false)*one_transition(b-1,x-1,false)*one_transition(c,y,true)*one_transition(d,z,true);}
int demand_units(int e,bool fail,int zone){int q1,q2,h1,h2;decode(e,q1,q2,h1,h2);return fail?(zone==1?q1:q2):q1+q2;}
void weight_walk(bool fail,int zone,int horizon,int depth,int state,int demand,std::uint64_t probability,std::array<int,6>&path,int k,int accrued,Weight&w){if(depth==horizon-k){constexpr std::uint64_t L=5354228880ULL;Big add=Big::make(probability).times(L/(accrued+demand));if(fail)w.accrued_fail.plus(add);else w.accrued_total.plus(add);for(int j=k;j<=horizon;++j){if(fail)w.fail[j][path[j-k]].plus(add);else w.total[j][path[j-k]].plus(add);}return;}for(int next=0;next<16;++next){path[depth+1]=next;weight_walk(fail,zone,horizon,depth+1,next,demand+demand_units(next,fail,zone),probability*transition(state,next),path,k,accrued,w);}}
Weight weights(const bpcr_general::GBcrhInput&in){Weight w;int first=state_index_local(in.demand1,in.demand2,in.blocked1,in.blocked2);std::array<int,6>path{};path[0]=first;weight_walk(false,in.failed_zone,5,0,first,demand_units(first,false,in.failed_zone),1,path,in.epoch,(int)(in.accrued_total_demand/20),w);if(in.epoch<=2){weight_walk(true,in.failed_zone,2,0,first,demand_units(first,true,in.failed_zone),1,path,in.epoch,(int)(in.accrued_fail_demand/20),w);w.scale=15625000000ULL;}return w;}
S build(const bpcr_general::GBcrhInput&in){S s;s.failed=in.failed_zone;s.time=20*in.epoch;for(int t=0;t<4;++t)s.clear[t]=in.clearance[t];for(int i=0;i<in.active_count;++i){const auto&x=in.agents[i];s.a.push_back(A{x.rank,x.opaque_rank,x.fast,x.radio,x.node,x.edge_from,x.edge_to,x.edge_remaining,x.destination_node,x.token,x.token_state,x.acquisition_elapsed,x.energy_fifths});}return s;}
Schedule persist(const bpcr_general::GBcrhInput&in,const S&initial,const C&candidate){Schedule out;for(int exogenous=15;exogenous>=0;--exogenous){S state=initial;std::array<int,4>live=candidate.o;if(apply(state,candidate))throw std::logic_error("checker apply");for(int epoch=in.epoch;epoch<6;++epoch){if(epoch!=in.epoch){C command;for(int token=3;token>=0;--token){command.o[token]=live[token];int ai=find(state,live[token]);if(live[token]!=NUL&&ai>=0&&!moving(state.a[ai])&&contingency(state,state.a[ai],token).second<0){live[token]=NUL;command.o[token]=NUL;}}if(apply(state,command))throw std::logic_error("checker persist");}int q1,q2,h1,h2;decode(exogenous,q1,q2,h1,h2);for(int second=19;second>=0;--second){auto d=delivery(state,q1,q2,h1,h2);out.d[0][epoch][exogenous]+=d[0];out.d[1][epoch][exogenous]+=d[1];tick(state,q1,q2,h1,h2);}}}return out;}
std::pair<int,int> floor_value(const bpcr_general::GBcrhInput&in,const Schedule&s){if(in.epoch>2)return{0,1};int bestn=2,bestd=1;for(int q1=1;q1<=2;++q1)for(int h1=0;h1<=1;++h1)for(int q2=1;q2<=2;++q2)for(int h2=0;h2<=1;++h2){int n=(int)in.accrued_fail_delivered,d=(int)in.accrued_fail_demand;int states[3]={state_index_local(in.demand1,in.demand2,in.blocked1,in.blocked2),state_index_local(in.failed_zone==1?q1:in.demand1,in.failed_zone==1?in.demand2:q1,in.failed_zone==1?h1:in.blocked1,in.failed_zone==1?in.blocked2:h1),state_index_local(in.failed_zone==1?q2:in.demand1,in.failed_zone==1?in.demand2:q2,in.failed_zone==1?h2:in.blocked1,in.failed_zone==1?in.blocked2:h2)};for(int j=in.epoch;j<=2;++j){n+=s.d[in.failed_zone-1][j][states[j-in.epoch]];int a,b,c,e;decode(states[j-in.epoch],a,b,c,e);d+=20*(in.failed_zone==1?a:b);}if((std::int64_t)n*bestd<(std::int64_t)bestn*d){bestn=n;bestd=d;}}int divisor=std::gcd(bestn,bestd);return{bestn/divisor,bestd/divisor};}
Score score(const bpcr_general::GBcrhInput&in,const S&state,const C&candidate,const Weight&w){Schedule schedule=persist(in,state,candidate);Big total=w.accrued_total.times((std::uint64_t)in.accrued_total_delivered),fail;if(in.epoch<=2)fail=w.accrued_fail.times((std::uint64_t)in.accrued_fail_delivered);for(int e=15;e>=0;--e)for(int j=5;j>=in.epoch;--j){total.plus(w.total[j][e].times(schedule.d[0][j][e]+schedule.d[1][j][e]));if(in.epoch<=2&&j<=2)fail.plus(w.fail[j][e].times(schedule.d[in.failed_zone-1][j][e]));}if(in.epoch<=2)total.plus(fail.times(w.scale));auto f=floor_value(in,schedule);Score out;out.fn=f.first;out.fd=f.second;out.objective=total;for(auto it=state.a.rbegin();it!=state.a.rend();++it)if(it->state==2&&it->token>=0&&candidate.o[it->token]!=it->rank)out.releases++;for(int t=0;t<4;++t)out.serial[t]=candidate.o[t]==NUL?1000000:state.a[find(state,candidate.o[t])].opaque;return out;}
bool better(const Score&a,const Score&b){std::int64_t left=(std::int64_t)a.fn*b.fd,right=(std::int64_t)b.fn*a.fd;if(left!=right)return left>right;if(a.objective!=b.objective)return a.objective>b.objective;if(a.releases!=b.releases)return a.releases<b.releases;return a.serial<b.serial;}
Evaluation evaluate(const bpcr_general::GBcrhInput&in){S state=build(in);auto commands=enumerate(state);Weight w=weights(in);Evaluation out;for(const auto&command:commands)out.records.push_back(Record{command,score(in,state,command,w)});for(std::size_t i=1;i<out.records.size();++i)if(better(out.records[i].score,out.records[out.selected].score))out.selected=i;std::uint64_t h=1469598103934665603ULL;for(const auto&r:out.records){for(int x:r.command.o){h^=(std::uint64_t)(x+1);h*=1099511628211ULL;}h^=r.score.fn;h*=1099511628211ULL;h^=r.score.fd;h*=1099511628211ULL;for(auto x:r.score.objective.x){h^=x;h*=1099511628211ULL;}}out.digest=h;return out;}
}
